sp_CriarPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_CriarPedido`(\n\n    p_cliente_id     INT,\n\n    p_usuario_id     INT,\n\n    p_idEmpresa      INT,\n\n    p_endereco_id    INT,\n\n    p_canal          VARCHAR(50),\n\n    p_numeroExterno  VARCHAR(100),\n\n    p_statusPedido_id TINYINT UNSIGNED,\n\n    p_valorTotal     DECIMAL(10,2),\n\n    p_valorFrete     DECIMAL(10,2),\n\n    p_Desconto       DECIMAL(10,2),\n\n    p_Observacao     VARCHAR(300)\n\n)\nBEGIN\n\n    DECLARE v_numero INT;\n\n    SELECT IFNULL(MAX(numeroPedido), 0) + 1 INTO v_numero FROM Pedido WHERE idEmpresa = p_idEmpresa;\n\n\n\n    INSERT INTO Pedido (\n\n        numeroPedido, cliente_id, usuario_id, statusPedido_id,\n\n        dthPedido, valorTotal, valorFrete, Desconto, Observacao,\n\n        endereco_id, idEmpresa, canal, numeroExterno\n\n    ) VALUES (\n\n        v_numero, p_cliente_id, p_usuario_id, p_statusPedido_id,\n\n        CURDATE(), p_valorTotal, p_valorFrete, p_Desconto, p_Observacao,\n\n        p_endereco_id, p_idEmpresa, p_canal, p_numeroExterno\n\n    );\n\n\n\n    SELECT LAST_INSERT_ID() AS idPedido;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
